sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    var parentId = current.parent || current.parent_complaint;
    if (!parentId) return;

    var parentComplaint = new GlideRecord('x_1958581_retail_0_retail_complaint');
    if (!parentComplaint.get(parentId)) return;

    var updated = false;

    // When store escalation task is Closed Complete (state 3 or 7)
    if (current.state == 3 || current.state == 7) {
        var reason = current.closure_reason || current.close_notes || "Investigation finished.";
        parentComplaint.state = 6; // Resolved
        parentComplaint.close_notes = "Store escalation completed: " + reason;
        parentComplaint.work_notes = "Linked Store Task " + current.number + " closed. Reason: " + reason;
        updated = true;
    }

    if (updated) {
        parentComplaint.update();
    }
})(current, previous);
